// portsData.ts
// Dataset ampliado para la herramienta "Puertos y Servicios" de VaultNotes.
// 100% offline — esta tabla alimenta el componente ToolsView.
//
// Cada entrada incluye:
//   - description: qué es el puerto y para qué sirve.
//   - security:    riesgos clásicos que un analista SOC debe vigilar.
//   - secure:      "Cómo ponerlo seguro" — 2-4 pasos concretos de hardening.
//   - detection:   comandos para ver si está activo / bajo ataque.
//
// Ordenado por número de puerto ascendente. No usar `export default`.

export interface PortInfo {
  port: number;
  proto: 'TCP' | 'UDP' | 'TCP/UDP';
  service: string;
  short: string;
  category: string;       // 'File' | 'Remote' | 'Mail' | 'Infra' | 'Web' | 'IAM' | 'Windows' | 'DB' | 'Directory' | 'VoIP' | 'Other'
  description: string;
  security: string;      // riesgos — texto existente conservado
  secure: string;        // NUEVO: hardening concreto ("Cómo ponerlo seguro")
  detection: { label: string; cmd: string }[];
  cve?: string;
}

